  if (!raw || r.error) return { json: { statusCode: r.statusCode || 200, body: '', error: r.error || undefined } };
  let body = '';
  if (req.fonte === 'zoom') {
    const m = raw.match(/<script[^>]*id\s*=\s*["']__NEXT_DATA__["'][^>]*>([\s\S]*?)<\/script>/i);
    if (m) {
      if (m[0].length <= 250000) {
        body = m[0];
