        .replace(/<svg\b[^>]*>[\s\S]*?<\/svg>/gi, '')
        .replace(/<!--[\s\S]*?-->/g, '')
        .replace(/[ \t]{2,}/g, ' ')
        .slice(0, 220000);
    }
  }
  return { json: { statusCode: r.statusCode || 200, body } };
});

